#ifndef OOT_H
#define OOT_H
/* Ocarina of Time sequence export: instrument catalog, MIDI-to-MML conversion, soundfont XML and
   zeldaret/oot repository patches. No editor, UI toolkit or file I/O. */
#include "duckmidi_export_plugin.h"
#include "duckmidi_midi.h"
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* ---- Catalog (catalog_data.c is generated by tools/oot_catalog.c) ---- */

/* One sample of an instrument: MIDI keys lo..hi, the sample in bank 0, its rate and root key. */
typedef struct {
    uint8_t lo, hi;
    uint16_t sample;
    double rate;
    int base;
} OotRegion;

typedef struct {
    const char *name;
    uint8_t font, program;  /* First vanilla soundfont and program that define it. */
    const char *attributes; /* Sample attributes of the vanilla <Instrument> element. */
    uint16_t release;
    uint8_t point_count;
    int16_t points[32][2];
    uint8_t region_count;
    OotRegion regions[3];
} OotInstrument;

/* A vanilla drum: one sample spread over keys lo..hi, rising a semitone per key from `base`. */
typedef struct {
    const char *kit, *sound;
    uint8_t font;
    uint16_t sample;
    uint8_t lo, hi;
    int base;
    double rate;
    uint8_t pan;
    uint16_t release;
    uint8_t point_count;
    int16_t points[32][2];
} OotDrum;

/* Instruments: font, program, catalog index. Drums: font, last key in that font, drum index. */
typedef struct {
    int16_t font, program, index;
} OotFontEntry;

extern const OotInstrument oot_instruments[];
extern const unsigned oot_instrument_count;
extern const OotDrum oot_drums[];
extern const unsigned oot_drum_count;
extern const OotFontEntry oot_font_entries[];
extern const unsigned oot_font_entry_count;
extern const OotFontEntry oot_font_drums[];
extern const unsigned oot_font_drum_count;

/* Mapping values: catalog instruments, then the driver's synthetic waves, then silence. */
#define OOT_SYNTH_BASE 200
#define OOT_SYNTH_COUNT 5
#define OOT_SILENT 999
#define OOT_CUSTOM_FONT (-1)
#define OOT_MAX_RATE 3.99996 /* Audio_NoteSetResamplingRate clamps above this. */

bool oot_instrument_valid(int value);
bool oot_drum_valid(int value);
int oot_synth_wave(int value);        /* Wave instrument number (128+), or -1. */
const char *oot_font_title(int font); /* "Main Orchestra", or NULL for unknown fonts. */
bool oot_music_font(int font);        /* A catalog font usable as a vanilla soundfont. */
void oot_instrument_label(int value, char *out, size_t capacity);
void oot_drum_label(int value, char *out, size_t capacity);
int oot_font_program(int font, int value); /* Program in that font, or -1. */
int oot_font_drum_hi(int font, int drum);  /* Last key of that drum in the font, or -1. */
int oot_default_instrument(int font, unsigned gm_program);
int oot_default_drum(int font, unsigned key);
int oot_instrument_class(int value);
int oot_drum_class(int drum);
int oot_gm_drum_class(unsigned key);
/* Choices for a mapping list: every catalog instrument/drum, or those of one vanilla font. */
unsigned oot_instrument_choices(int font, DmeChoice *choices, char (*labels)[96], unsigned max);
unsigned oot_drum_choices(int font, DmeChoice *choices, char (*labels)[96], unsigned max);
/* Playback rate of `key` relative to the sample's own rate; above OOT_MAX_RATE it clamps. */
double oot_instrument_rate(int value, unsigned key);
unsigned oot_drum_key(int font, int drum, unsigned key); /* The vanilla key that plays `key`. */
double oot_drum_rate(int font, int drum, unsigned key);

/* ---- Text ---- */

typedef struct {
    char *data;
    size_t size, capacity;
    bool failed;
} OotText;

void oot_text_add(OotText *text, const char *format, ...);
void oot_text_append(OotText *text, const char *data, size_t size);
void oot_text_free(OotText *text);
void oot_note_name(int key, char *out, size_t capacity); /* MIDI key as C4, EF3, BNEG1 */

/* ---- Conversion ---- */

enum { OOT_LOOP_NONE, OOT_LOOP_SONG, OOT_LOOP_REGION };

typedef struct {
    const DmeEvent *events; /* Channel messages already moved to their output channels. */
    uint64_t event_count, duration;
    uint32_t ppq;
    uint32_t loop; /* OOT_LOOP_*; REGION repeats [loop_start, loop_end) after an intro. */
    uint64_t loop_start, loop_end;
    int instruments[16][128]; /* Mapping value per channel and GM program. */
    int drums[128];           /* Drum index per GM key on MIDI channel 10, or OOT_SILENT. */
    int font;                 /* OOT_CUSTOM_FONT or a vanilla font index. */
    int font_index;           /* Index written into a custom soundfont. */
    uint32_t volume;          /* Sequence volume, 1..127. */
    bool enlarge_memory;      /* Caches grow to fit, so scene memory needs no warning. */
    const char *name;         /* File stem: lowercase letters, digits and _. */
} OotRequest;

typedef struct {
    uint32_t severity;
    char text[320];
} OotDiagnostic;

/* Notes that the mapped sample cannot reach. `program` is the GM program or drum key. */
typedef struct {
    uint32_t channel, program, low, high, count;
    bool percussion;
    double rate;
} OotRangeIssue;

typedef struct {
    OotText sequence, soundfont; /* soundfont stays empty for a vanilla font */
    uint64_t sequence_bytes, soundfont_bytes;
    OotDiagnostic *diagnostics;
    size_t diagnostic_count, diagnostic_capacity;
    OotRangeIssue *ranges;
    size_t range_count, range_capacity;
    unsigned channels, instruments, drums;
} OotResult;

/* Converts, or only analyzes ranges when `analyze` is true. host may be NULL; its cancelled and
   progress callbacks are used when present. */
int32_t oot_convert(const OotRequest *request, const DmeHost *host, bool analyze, OotResult *result,
                    char *error, size_t capacity);
void oot_result_free(OotResult *result);
bool oot_range_supported(const OotRequest *request, const OotRangeIssue *issue, int value);
bool oot_font_range_supported(int font, const OotRangeIssue *issue, int value);
bool oot_name_valid(const char *name);

/* ---- Audio memory (vanilla gAudioSpecs, src/audio/game/session_config.c) ---- */

#define OOT_SEQ_CACHE_MIN 0x2800u    /* Smallest temporary sequence cache (spec 10). */
#define OOT_SEQ_CACHE_COMMON 0x3800u /* Most scenes. */
#define OOT_FONT_CACHE 0x2600u       /* Smallest temporary font cache (spec 17). */
#define OOT_HEAP_SIZE 0x38000u

/* ---- Repository patches ---- */

#define OOT_SEQUENCE_TABLE "include/tables/sequence_table.h"
#define OOT_SPEC "spec/spec"
#define OOT_SESSION_CONFIG "src/audio/game/session_config.c"
#define OOT_AUDIO_HEAP_C "src/buffers/audio_heap.c"
#define OOT_BUFFERS_H "include/buffers.h"

typedef struct {
    const char *id, *label; /* NA_BGM_* and a readable name */
} OotSong;

extern const OotSong oot_songs[];
extern const unsigned oot_song_count;

/* Replaces the sequence of `song` (an NA_BGM_* name), or adds a new NA_BGM_<NAME> when song is
   NULL. A song too large for the persistent cache moves to the temporary one, explained in
   `notice`. Fails without output when the table is not the expected format. */
bool oot_patch_sequence_table(const uint8_t *data, uint64_t size, const char *name,
                              const char *song, uint64_t sequence_bytes, OotText *out, char *notice,
                              size_t notice_capacity, char *error, size_t capacity);
/* Adds the sequence and, when font is true, the soundfont objects to spec/spec. */
bool oot_patch_spec(const uint8_t *data, uint64_t size, const char *name, bool font, OotText *out,
                    char *error, size_t capacity);
/* Next soundfont index from spec/spec's Audiobank segment, or -1. */
int oot_next_font_index(const uint8_t *data, uint64_t size, const char *name);

/* The sequence ID a song takes: the replaced song's NA_BGM_* or NA_BGM_<NAME> for a new one. */
void oot_song_id(const char *name, const char *song, char *out, size_t capacity);

enum { OOT_SONG_NAME_CAPACITY = 64 };

/* Custom songs a spec includes: sequences other than seq_N and soundfonts other than
   Soundfont_N, each name once. */
size_t oot_custom_songs(const uint8_t *data, uint64_t size, char names[][OOT_SONG_NAME_CAPACITY],
                        size_t capacity);
/* Custom soundfonts in spec order; vanilla counts the Soundfont_N includes. */
size_t oot_custom_fonts(const uint8_t *data, uint64_t size, char names[][OOT_SONG_NAME_CAPACITY],
                        size_t capacity, unsigned *vanilla);
/* Whether Sequence_<song> stays in the sequence table once name is installed for song ID id. */
bool oot_song_kept(const uint8_t *table, uint64_t size, const char *song, const char *name,
                   const char *id);
/* The spec without the sequence and soundfont includes of the given custom songs. */
bool oot_spec_without(const uint8_t *data, uint64_t size, char names[][OOT_SONG_NAME_CAPACITY],
                      size_t count, OotText *out);
/* Raises every audio spec's temporary sequence/font cache below the given sizes and grows the
   audio heap by the largest increase. *growth receives that increase. */
bool oot_patch_session_config(const uint8_t *data, uint64_t size, uint32_t sequence_cache,
                              uint32_t font_cache, OotText *out, uint32_t *growth, char *error,
                              size_t capacity);
bool oot_patch_audio_heap(const uint8_t *data, uint64_t size, uint32_t growth, OotText *out,
                          char *error, size_t capacity);
char *oot_install_guide(const char *name, const char *song, bool font, int font_index,
                        uint64_t sequence_bytes, uint64_t font_bytes);
#endif
